from "@std/testing.ms" import TestHooks, expect_equal, expect_ok
from "@std/http.ms" import HttpServer, HttpRequest, HttpResponse, HttpMethod, headers
from "@std/net.ms" import network

type ApiFixture:
    server: HttpServer

def handle(request: HttpRequest) -> HttpResponse:
    return HttpResponse(status: 200, headers: headers(), body: "shared".to_bytes())

def make_fixture() -> ApiFixture:
    return ApiFixture(
        server: network().serve(address: "127.0.0.1:0", handler: handle).get()
    )

impl TestHooks for ApiFixture:
    def after_all() -> Unit:
        self.server.close()

test "first request":
    let response = try expect_ok(
        network().request(
            method: HttpMethod.Get, url: f"http://{fixture.server.address()}/",
            headers: headers(), body: ""
        )
    )
    try expect_equal(response.metadata().status, 200)

test "second request uses same server":
    let response = try expect_ok(
        network().request(
            method: HttpMethod.Get, url: f"http://{fixture.server.address()}/",
            headers: headers(), body: ""
        )
    )
    try expect_equal(response.body, "shared".to_bytes())
